            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Les phases d&#39;une bataille&lt;/a&gt;&lt;/li&gt;
